21	impl ReleaseProvider for RegistryProvider {
22	    fn capabilities(&self) -> ProviderCapabilities {
23	        // Every registry answers an observation. Whether that answer can be
24	        // exact is the adapter's `can_observe_versions`.
25	        ProviderCapabilities {
26	            can_observe: true,
27	            can_publish: true,
28	        }
29	    }
30	
31	    fn observe(
32	        &self,
33	        context: &ProviderContext<'_>,
34	        request: &ProviderRequest<'_>,
35	    ) -> Result<ProviderObservationV1, GraphError> {
36	        let operation = registry_operation(request)?;
37	        registry_observation(adapter_for(request.id.package.ecosystem())?, context, operation)
38	    }
39	
40	    fn preflight_conflict(&self) -> RemoteConflict {
41	        RemoteConflict::RegistryVersionDiffers
42	    }
43	
44	    fn preflight(
45	        &self,
46	        context: &ProviderContext<'_>,
47	        request: &ProviderRequest<'_>,
48	    ) -> Result<ReleasePreflight, GraphError> {
49	        match self.observe(context, request)? {
50	            // A registry with no query API at all has nothing to observe
51	            // before the effect; the post-effect confirmation fails closed.
52	            ProviderObservationV1::Indeterminate {
53	                cause: ProviderIndeterminateCause::UnsupportedProvider,
54	            } => Ok(proceed()),
55	            observation => preflight_from_observation(observation, request.id, self.preflight_conflict()),
56	        }
57	    }
58	
59	    fn publish(
60	        &self,
61	        context: &ProviderContext<'_>,
62	        request: &ProviderRequest<'_>,
63	        _effect: &EffectAuthorization<'_>,
64	    ) -> Result<ExactEvidence, GraphError> {
65	        let operation = registry_operation(request)?;
66	        let adapter = adapter_for(request.id.package.ecosystem())?;
67	        let output = adapter.publish(context, operation)?;
68	        let outcome = adapter.classify(&output).map_err(|source| GraphError::Registry {
69	            package: operation.package_name.clone(),
70	            source,
71	        })?;
72	        // Neither a zero exit nor the client's "already exists" text is a
73	        // receipt: a yanked version is not the version this intent authorized,
74	        // so only an exact observation may satisfy the operation.
75	        let confirmed = if matches!(outcome, PublishOutcome::Published) && adapter.can_observe_versions() {
76	            confirmed_registry_observation(adapter, context, operation)?
77	        } else {
78	            registry_observation(adapter, context, operation)?
79	        };
80	        require_registry_confirmation(
81	            confirmed.is_terminal_success(),
82	            &operation.package_name,
83	            &operation.version,
84	        )?;
85	        confirmed
86	            .exact_evidence()
87	            .ok_or_else(|| GraphError::RegistryPublishUnconfirmed {
88	                package: operation.package_name.clone(),
89	                version: operation.version.clone(),
90	            })
91	    }
92	}
