94	fn proceed() -> ReleasePreflight {
95	    ReleasePreflight::Proceed {
96	        proof: ProviderObservationV1::Absent
97	            .absent_proof()
98	            .expect("an absent observation mints an absent proof"),
99	    }
100	}
