109	/// The one registry observation used by preflight and post-publish
110	/// confirmation, so the two can never disagree.
111	fn registry_observation(
112	    adapter: &'static dyn RegistryEcosystem,
113	    context: &ProviderContext<'_>,
114	    operation: &RegistryPublishOperation,
115	) -> Result<ProviderObservationV1, GraphError> {
116	    if !adapter.can_observe_versions() {
117	        return Ok(ProviderObservationV1::Indeterminate {
118	            cause: ProviderIndeterminateCause::UnsupportedProvider,
119	        });
120	    }
121	    policy::retry_observation(context.sleeper(), || adapter.observe_once(context, operation))
122	}
