124	/// The same observation, but an absence is treated as index-propagation lag
125	/// rather than an answer: this only runs after a publish client reported the
126	/// version as newly published.
127	fn confirmed_registry_observation(
128	    adapter: &'static dyn RegistryEcosystem,
129	    context: &ProviderContext<'_>,
130	    operation: &RegistryPublishOperation,
131	) -> Result<ProviderObservationV1, GraphError> {
132	    policy::retry_observation(context.sleeper(), || {
133	        Ok(match adapter.observe_once(context, operation)? {
134	            Attempt::Settled(ProviderObservationV1::Absent) => Attempt::Transient {
135	                value: ProviderObservationV1::Absent,
136	                retry_after: None,
137	            },
138	            settled_or_transient => settled_or_transient,
139	        })
140	    })
141	}
