305	/// The observation argv: `cargo info NAME@VERSION --registry REGISTRY`.
306	///
307	/// `--registry` is never omitted. Without it `cargo info` resolves the local
308	/// workspace and reports an unpublished member's on-disk version as published
309	/// (`version: X (from ./)`), which is the defect this observation exists to
310	/// avoid; with it, cargo reads only the named registry.
311	///
312	/// `net.retry=0` must precede `info` (cargo ignores it after the subcommand):
313	/// callisto's bounded retry owns retrying, and cargo's own backoff inside each
314	/// attempt made an unreachable registry take ~11s per attempt.
315	fn cargo_info_args<'a>(spec: &'a str, registry: &'a str) -> [&'a str; 6] {
316	    ["--config", "net.retry=0", "info", spec, "--registry", registry]
317	}
