324	    /// Runs from the source workspace root, so the same `.cargo/config.toml`
325	    /// registry definitions and credentials the publish effect uses apply --
326	    /// private registries and their auth are cargo's business, not ours.
327	    fn observe_once(
328	        &self,
329	        context: &ProviderContext<'_>,
330	        operation: &RegistryPublishOperation,
331	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
332	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
333	        let registry = cargo_registry_name(&operation.registry.key);
334	        let args = cargo_info_args(&spec, registry);
335	        let output = match run_observation(
336	            context.runner(),
337	            programs::CARGO,
338	            &args,
339	            context.root(),
340	            timeouts::REGISTRY_QUERY,
341	            true,
342	        )? {
343	            Ok(output) => output,
344	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
345	        };
