371	/// Classifies one real `cargo info` run. There is no `--json`, so the two
372	/// answers cargo actually proves are read from its exit code and its text:
373	///
374	/// - exit 0 with a `version: VERSION` line for the requested version: `Exact`.
375	///   `cargo info` reports neither the index checksum nor the yank flag, so the
376	///   evidence says `None` for both rather than inventing them.
377	/// - exit 101 with ``could not find `NAME@VERSION` ``: `Absent`.
378	/// - anything else -- another exit code, another message (a network failure
379	///   prints ``failed to load source for dependency``), or a zero exit with no
380	///   matching version line: transient `Indeterminate`, retried by the bounded
381	///   policy. An unreachable registry must never read as an absence.
382	///
383	/// A *yanked* version reads as `Absent`, because `cargo info` cannot see yanks
384	/// and answers "could not find" for one. That fails closed rather than open:
385	/// the publish attempt that follows is refused by the registry, and since only
386	/// an `Exact` observation may satisfy an operation, the run ends in the typed
387	/// `RegistryPublishUnconfirmed` error instead of a receipt.
388	fn classify_cargo_info(output: &CommandOutput, spec: &str, version: &Version) -> Attempt<ProviderObservationV1> {
389	    if output.success() {
390	        return if reports_version(&output.stdout, version) {
391	            settled(ProviderObservationV1::Exact {
392	                evidence: ProviderEvidenceV1::RegistryVersion {
393	                    version: version.clone(),
394	                    checksum: None,
395	                    yanked: None,
396	                },
397	            })
398	        } else {
399	            transient(ProviderIndeterminateCause::MalformedResponse, None)
400	        };
401	    }
402	    if output.exit_code == Some(101) && output.stderr.contains(&format!("could not find `{spec}`")) {
403	        return settled(ProviderObservationV1::Absent);
404	    }
405	    transient(ProviderIndeterminateCause::CommandFailed, None)
406	}
407	
408	/// Whether cargo's `version: X ...` line names exactly the requested version.
409	fn reports_version(stdout: &str, version: &Version) -> bool {
410	    stdout.lines().any(|line| {
411	        line.trim()
412	            .strip_prefix("version: ")
413	            .and_then(|rest| rest.strip_prefix(version.render()))
414	            .is_some_and(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
415	    })
416	}
