425	    /// `npm view` keeps the workspace cwd: unlike a manifest-resolving client
426	    /// it never reads the local package, and the cwd is only where the project
427	    /// `.npmrc` supplying the registry is read from.
428	    fn observe_once(
429	        &self,
430	        context: &ProviderContext<'_>,
431	        operation: &RegistryPublishOperation,
432	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
433	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
434	        // Callisto's bounded retry owns retrying; npm's own fetch retries made an
435	        // unreachable registry take ~70s per attempt.
436	        let mut args = vec!["view", spec.as_str(), "--json", "--fetch-retries=0"];
437	        if let Some(registry) = operation.registry.endpoint.as_deref() {
438	            args.extend(["--registry", registry]);
439	        }
440	        let output = match run_observation(
441	            context.runner(),
442	            programs::NPM,
443	            &args,
444	            context.root(),
445	            timeouts::REGISTRY_QUERY,
446	            true,
447	        )? {
448	            Ok(output) => output,
449	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
450	        };
451	        if output.success() {
452	            return Ok(if output.stdout_trimmed().is_empty() {
453	                settled(ProviderObservationV1::Absent)
454	            } else {
455	                // `npm view` reports no package checksum, so the evidence says
456	                // so rather than inventing one.
457	                settled(ProviderObservationV1::Exact {
458	                    evidence: ProviderEvidenceV1::RegistryVersion {
459	                        version: operation.version.clone(),
460	                        checksum: None,
461	                        yanked: None,
462	                    },
463	                })
464	            });
465	        }
466	        let details = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
467	        if details.contains("e404")
468	            || details.contains("etarget")
469	            || details.contains("no matching version")
470	            || details.contains("is not in this registry")
471	        {
472	            return Ok(settled(ProviderObservationV1::Absent));
473	        }
474	        Ok(transient(ProviderIndeterminateCause::CommandFailed, None))
475	    }
