511	struct PypiRegistry;
512	
513	/// PyPI's own PEP 691 JSON simple index, not `pip`: `pip index versions` is
514	/// experimental and hides yanked releases, and an unreachable index and a
515	/// missing project both look like "no versions found" to it. The index itself
516	/// answers plainly -- 200 with a `files[]` entry naming the version, or 404 --
517	/// so observation goes straight to `https://pypi.org/simple/<project>/`
518	/// (or the configured private index) over `curl`, never through `pip`.
519	const PYPI_DEFAULT_SIMPLE_INDEX: &str = "https://pypi.org/simple";
520	
521	/// PEP 691: the versioned JSON media type, so the index cannot fall back to
522	/// the legacy HTML page a bare GET would otherwise serve.
523	const PYPI_SIMPLE_ACCEPT: &str = "application/vnd.pypi.simple.v1+json";
524	
525	/// The project's simple-index URL: the configured private index if one is
526	/// bound (already https-validated in `binding.rs`), else the public default.
527	fn pypi_simple_index_url(endpoint: Option<&str>, package_name: &str) -> String {
528	    let base = endpoint.unwrap_or(PYPI_DEFAULT_SIMPLE_INDEX);
529	    let project = normalize_pypi_project_name(package_name);
530	    format!("{}/{project}/", base.trim_end_matches('/'))
531	}
532	
533	/// One file entry of a PEP 691 JSON simple-index response -- only the fields
534	/// the observation reads.
535	#[derive(serde::Deserialize)]
536	struct PypiSimpleFile {
537	    filename: String,
538	    /// `false` when not yanked, or a (possibly empty) reason string when it is.
539	    #[serde(default)]
540	    yanked: Option<serde_json::Value>,
541	}
542	
543	#[derive(serde::Deserialize)]
544	struct PypiSimpleIndex {
545	    files: Vec<PypiSimpleFile>,
546	}
547	
548	impl PypiSimpleFile {
549	    fn is_yanked(&self) -> bool {
550	        !matches!(self.yanked, None | Some(serde_json::Value::Bool(false)))
551	    }
552	}
553	
554	/// The version segment of a simple-index filename, or `None` for an extension
555	/// this parser does not recognize (a legacy installer, say).
556	///
557	/// A wheel's distribution segment is PEP 427-escaped to underscores only, so
558	/// splitting on `-` unambiguously yields `version` second. A PEP 440 version
559	/// never itself contains a hyphen, so an sdist's *last* `-` is always the
560	/// name/version boundary regardless of how the distribution name is spelled.
561	fn pypi_simple_file_version(filename: &str) -> Option<&str> {
562	    if let Some(stem) = filename.strip_suffix(".whl") {
563	        return stem.split('-').nth(1);
564	    }
565	    [".tar.gz", ".tar.bz2", ".tar.xz", ".tar.Z", ".zip"]
566	        .into_iter()
567	        .find_map(|ext| filename.strip_suffix(ext))
568	        .and_then(|stem| stem.rsplit_once('-'))
569	        .map(|(_, version)| version)
570	}
571	
572	/// Whether a simple-index file's filename names exactly the requested version.
573	fn pypi_simple_file_matches(file: &PypiSimpleFile, version: &Version) -> bool {
574	    pypi_simple_file_version(&file.filename).is_some_and(|candidate| {
575	        Version::parse(candidate, version.grammar())
576	            .is_ok_and(|candidate| candidate.compare(version) == Ok(std::cmp::Ordering::Equal))
577	    })
578	}
579	
580	/// Classifies a parsed 200 body: the matching file's yank status decides the
581	/// answer, mirroring cargo's yanked-is-absent rationale above -- a yanked
582	/// release is not the version this intent authorized, so it fails closed.
583	fn classify_pypi_simple_body(body: &str, version: &Version) -> Attempt<ProviderObservationV1> {
584	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
585	        return transient(ProviderIndeterminateCause::MalformedResponse, None);
586	    };
587	    let matching = index
588	        .files
589	        .iter()
590	        .filter(|file| pypi_simple_file_matches(file, version));
591	    let mut matched = false;
592	    for file in matching {
593	        if file.is_yanked() {
