610	/// Classifies one `curl -sS -i` run against the simple index. A private index
611	/// that ignores `Accept` and serves its legacy HTML page fails the JSON parse
612	/// inside [`classify_pypi_simple_body`] and reads as `MalformedResponse`, same
613	/// as any other body PEP 691 JSON parsing cannot make sense of.
614	///
615	/// Any other status shares [`HttpResponse::is_transient`] with GitHub's `gh api` reads, so it retries on
616	/// `Retry-After` instead of settling immediately, and either way reports the status as `ProviderStatus`.
617	fn classify_pypi_simple(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
618	    let response = match parse_http_response(&output.stdout) {
619	        Ok(response) => response,
620	        Err(_) if !output.success() => return transient(ProviderIndeterminateCause::CommandFailed, None),
621	        Err(_) => return transient(ProviderIndeterminateCause::MalformedResponse, None),
622	    };
623	    match response.status {
624	        200 => classify_pypi_simple_body(&response.body, version),
625	        404 => settled(ProviderObservationV1::Absent),
626	        status if response.is_transient() => transient(
627	            ProviderIndeterminateCause::ProviderStatus { status },
628	            response.retry_after(),
629	        ),
630	        status => settled(ProviderObservationV1::Indeterminate {
631	            cause: ProviderIndeterminateCause::ProviderStatus { status },
632	        }),
633	    }
634	}
