156	/// Builds a release intent from a fresh root-bound observation.
157	pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
158	    root: &Path,
159	    locator: &L,
160	    runner: &R,
161	    decision: &ReleaseDecisionV1,
162	    trust_profile: ExecutionTrustProfileV1,
163	) -> Result<ReleaseIntentV1, GraphError> {
164	    let root = canonical_root(root)?;
165	    let workspace = Workspace::load(root.clone(), locator, runner)?;
166	    let source = observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)?;
167	    let intent = derive_release_intent(
168	        &workspace,
169	        decision,
170	        source.clone(),
171	        trust_profile,
172	        None,
173	        GitRemoteRequirement::Required,
174	        &mut Vec::new(),
175	    )?;
176	
177	    // Recheck after all input reads. A concurrent edit or checkout cannot be
178	    // authorized merely because it happened after the first check.
179	    if observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)? != source {
180	        return Err(GraphError::ReleaseIntentStale {
181	            reason: StaleReason::source_identity_changed(),
182	        });
183	    }
184	    Ok(intent)
185	}
