243	fn validate_intent<'a, L: ProjectLocator, R: CommandRunner>(
244	    root: &Path,
245	    locator: &L,
246	    runner: &'a R,
247	    received: ReleaseIntentV1,
248	    checkout: ReleaseCheckout,
249	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
250	    let root = canonical_root(root)?;
251	    let workspace = Workspace::load(root.clone(), locator, runner)?;
252	    let trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
253	    let source = source_from_trust(&trust);
254	    let artifact_policy = artifact_policy_from_intent(&received)?;
255	    // This is an integrity re-derivation, not a fresh plan: any diagnostic it would
256	    // raise was already surfaced when `received` was first derived.
257	    let (expected, prepared) = derive_release_intent_with_prepared(
258	        &workspace,
259	        &received.decision,
260	        source.clone(),
261	        received.trust_profile,
262	        artifact_policy.as_ref(),
263	        &mut Vec::new(),
264	    )?;
265	    let final_trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
266	    if expected != received || final_trust.identity() != trust.identity() {
267	        return Err(GraphError::ReleaseIntentStale {
268	            reason: StaleReason::intent_differs_from_fresh_derivation(),
269	        });
270	    }
271	
272	    // Plan time is the last point before any effect at which an unusable
273	    // provider is still cheap to reject.
274	    for operation in prepared.operations.values() {
275	        checked_provider_for(operation)?;
276	    }
277	
278	    Ok(ValidatedReleaseIntent {
279	        prepared: PreparedReleaseInputs {
280	            root,
281	            source,
282	            trust: final_trust,
283	            git_remote: prepared.git_remote,
284	            operations: prepared.operations,
285	        },
286	        intent: received,
287	        runner,
288	    })
289	}
