1	//! The release executor.
2	//!
3	//! Every run starts from a fresh in-memory state and observes each provider
4	//! before acting, so a rerun adopts whatever an earlier run already landed.
5	
6	use std::collections::{BTreeMap, BTreeSet};
7	
8	use callisto_model::{
9	    ApplyPermit, OperationEvent, OperationState, ReleaseExecutionStateV1, ReleaseIntentV1, ReleaseOperationId,
10	    ReleaseOperationRole, ReleaseRunEnvelopeV1, ReleaseStateError,
11	};
12	
13	use crate::GraphError;
