/// Finds drafts too, unlike `GET /releases/tags/{tag}`.
const RELEASE_ID_QUERY: &str = "query($owner:String!,$name:String!,$tagName:String!)\
{repository(owner:$owner,name:$name){release(tagName:$tagName){databaseId}}}";

/// `gh api` defines no `--repo`; the endpoint already carries owner and repository.
pub(crate) fn github_release_api_args(endpoint: &str) -> [&str; 5] {
    ["api", "--include", "--method", "GET", endpoint]
}

fn parse_github_api_response(program: &str, args: &[&str], stdout: &str) -> Result<HttpResponse, GraphError> {
    parse_http_response(stdout).map_err(|detail| GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(ToString::to_string).collect(),
        failure: CommandFailure::MalformedOutput { detail },
    })
}

/// `gh api --include` preserves the HTTP response even for a 404 and exits
/// non-zero. Parse that authoritative response first so absence is not
/// mistaken for a transport failure; retain the command failure when no
/// parseable HTTP response was produced.
fn github_api_response(program: &str, args: &[&str], output: &CommandOutput) -> Result<HttpResponse, GraphError> {
    match parse_github_api_response(program, args, &output.stdout) {
        Ok(response) => Ok(response),
        Err(_) if !output.success() => Err(GraphError::ReleaseCommand {
            program: program.to_owned(),
            args: args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::NonZeroExit {
                exit_code: output.exit_code,
                stderr: output.stderr.clone(),
            },
        }),
        Err(error) => Err(error),
    }
}

/// Classifies an HTTP response before parsing a GitHub Release body. A 404
/// proves absence; all other non-success statuses leave remote identity
/// unknown. In particular, authentication, rate-limit, and server failures
/// must never be reported as a conflicting release or asset.
fn github_release_response_status(status: u16) -> Option<GitHubReleaseLookup> {
    match status {
        200 => None,
        404 => Some(GitHubReleaseLookup::Absent),
        other => Some(GitHubReleaseLookup::Indeterminate { status: other }),
    }
}

/// GraphQL for the release ID by tag, then REST by ID: how `gh release view` finds drafts.
pub(crate) fn github_release_for_tag(
    root: &Path,
    runner: &dyn CommandRunner,
    sleeper: &dyn Sleeper,
    repository: &str,
    tag: &TagName,
) -> Result<GitHubReleaseLookup, GraphError> {
    let id = match retry_observation(sleeper, || github_release_id_once(root, runner, repository, tag))? {
        ReleaseIdLookup::Found(id) => id,
        ReleaseIdLookup::Unknown(lookup) => return Ok(lookup),
    };
    let endpoint = github_release_endpoint(repository, id);
    retry_observation(sleeper, || github_api_get_once(root, runner, &endpoint))
}

enum ReleaseIdLookup {
    Found(u64),
    Unknown(GitHubReleaseLookup),
}

fn github_release_id_once(
    root: &Path,
    runner: &dyn CommandRunner,
    repository: &str,
    tag: &TagName,
) -> Result<Attempt<ReleaseIdLookup>, GraphError> {
    let (owner, name) = repository
        .split_once('/')
        .ok_or_else(|| malformed_github_response(repository, "GitHub repository is not OWNER/NAME"))?;
    let query = format!("query={RELEASE_ID_QUERY}");
    let owner = format!("owner={owner}");
    let name = format!("name={name}");
    let tag_name = format!("tagName={tag}");
    let args = [
        "api",
        "--include",
        "graphql",
        "-f",
        &query,
        "-f",
        &owner,
        "-f",
        &name,
        "-f",
        &tag_name,
    ];
    let malformed = |detail: &str| GraphError::ReleaseCommand {
        program: programs::GH.to_owned(),
        args: args.iter().map(ToString::to_string).collect(),
        failure: CommandFailure::MalformedOutput {
            detail: detail.to_owned(),
        },
    };
    let transient = |value| {
        Ok(Attempt::Transient {
            value: ReleaseIdLookup::Unknown(value),
            retry_after: None,
        })
    };
    let observed = match run_observation(runner, programs::GH, &args, root, timeouts::FORGE_API, false)? {
        Ok(output) => output,
        Err(_unavailable) => return transient(GitHubReleaseLookup::CommandFailed),
    };
    let response = github_api_response(programs::GH, &args, &observed)?;
    if response.status != 200 {
        let lookup = GitHubReleaseLookup::Indeterminate {
            status: response.status,
        };
        return Ok(if response.is_transient() {
            Attempt::Transient {
                value: ReleaseIdLookup::Unknown(lookup),
                retry_after: response.retry_after(),
            }
        } else {
            Attempt::Settled(ReleaseIdLookup::Unknown(lookup))
        });
    }
    let value: serde_json::Value =
        serde_json::from_str(&response.body).map_err(|error| malformed(&error.to_string()))?;
    // GraphQL returns failures, rate limits included, as a 200 with `errors`.
    let repository_node = value.pointer("/data/repository").filter(|node| !node.is_null());
    let Some(repository_node) = repository_node.filter(|_| value.get("errors").is_none()) else {
        return transient(GitHubReleaseLookup::CommandFailed);
    };
    match repository_node.get("release") {
        Some(serde_json::Value::Null) => Ok(Attempt::Settled(ReleaseIdLookup::Unknown(GitHubReleaseLookup::Absent))),
        Some(release) => release
            .get("databaseId")
            .and_then(serde_json::Value::as_u64)
            .map(|id| Attempt::Settled(ReleaseIdLookup::Found(id)))
            .ok_or_else(|| malformed("GitHub release has no databaseId")),
        None => Err(malformed("GitHub response has no release field")),
    }
}

pub(crate) fn malformed_github_response(endpoint: &str, detail: &str) -> GraphError {
    GraphError::ReleaseCommand {
        program: programs::GH.to_owned(),
        args: github_release_api_args(endpoint)
            .iter()
            .map(ToString::to_string)
            .collect(),
        failure: CommandFailure::MalformedOutput {
            detail: detail.to_owned(),
        },
    }
}

fn github_api_get_once(
    root: &Path,
    runner: &dyn CommandRunner,
    endpoint: &str,
) -> Result<Attempt<GitHubReleaseLookup>, GraphError> {
    let api_args = github_release_api_args(endpoint);
    let observed = match run_observation(runner, programs::GH, &api_args, root, timeouts::FORGE_API, false)? {
        Ok(output) => output,
        Err(_unavailable) => {
            return Ok(Attempt::Transient {
                value: GitHubReleaseLookup::CommandFailed,
                retry_after: None,
    }
}

/// A release created for an existing tag reports the repository's default
/// branch as `target_commitish`, so that field proves nothing about the
/// released commit. The tag operation is a DAG prerequisite of the forge
/// release, so the tag already binds this release's name to its commit.
fn observed_forge_release(
    context: &ProviderContext<'_>,
    tag: &TagName,
    prerelease: bool,
    repository: &str,
    draft_policy: Draft,
) -> Result<ProviderObservationV1, GraphError> {
    let value = match github_release_for_tag(context.root(), context.runner(), context.sleeper(), repository, tag)? {
        GitHubReleaseLookup::Absent => return Ok(ProviderObservationV1::Absent),
        GitHubReleaseLookup::Indeterminate { status } => {
            return Ok(ProviderObservationV1::Indeterminate {
                cause: ProviderIndeterminateCause::ProviderStatus { status },
            })
        }
        GitHubReleaseLookup::CommandFailed => {
            return Ok(ProviderObservationV1::Indeterminate {
                cause: ProviderIndeterminateCause::CommandFailed,
            })
        }
        GitHubReleaseLookup::Found(value) => value,
    };
    if value.get("tag_name").and_then(serde_json::Value::as_str) != Some(tag.as_str()) {
        return Ok(ProviderObservationV1::Conflict {
            reason: ProviderConflictReason::ForgeReleaseDiffers,
        });
    }
    if value
        .get("prerelease")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
        != prerelease
    {
        return Ok(ProviderObservationV1::Conflict {
            reason: ProviderConflictReason::ForgeReleasePrereleaseDiffers,
        });
    }
    let draft = value.get("draft").and_then(serde_json::Value::as_bool).unwrap_or(false);
    if draft && draft_policy == Draft::PublishedOnly {
        return Ok(ProviderObservationV1::Absent);
    }
    Ok(ProviderObservationV1::Exact {
        evidence: ProviderEvidenceV1::ForgeRelease {
            tag_name: tag.clone(),
            draft,
        },
    })
}

